class MinHeap {
  constructor(less) {
    this.less = less
    this.items = []
  }

  get size() {
    return this.items.length
  }

  peek() {
    return this.items[0]
  }

  push(item) {
    const a = this.items
    a.push(item)
    let i = a.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (!this.less(a[i], a[parent])) break
      ;[a[i], a[parent]] = [a[parent], a[i]]
      i = parent
    }
  }

  pop() {
    const a = this.items
    const top = a[0]
    const last = a.pop()
    if (a.length > 0) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let best = i
        if (l < a.length && this.less(a[l], a[best])) best = l
        if (r < a.length && this.less(a[r], a[best])) best = r
        if (best === i) break
        ;[a[i], a[best]] = [a[best], a[i]]
        i = best
      }
    }
    return top
  }
}

function poolMakespan(durations, prereqs, k) {
  const n = durations.length
  const dependents = Array.from({ length: n }, () => [])
  const missing = prereqs.map(before => before.length)
  prereqs.forEach((before, task) => before.forEach(b => dependents[b].push(task)))
  const ready = new MinHeap((a, b) => a < b)
  for (let i = 0; i < n; i++) if (missing[i] === 0) ready.push(i)
  const running = new MinHeap((a, b) => a[0] < b[0])
  let now = 0
  let done = 0
  let idle = k
  while (ready.size > 0 || running.size > 0) {
    while (ready.size > 0 && idle > 0) {
      const task = ready.pop()
      running.push([now + durations[task], task])
      idle--
    }
    now = running.peek()[0]
    while (running.size > 0 && running.peek()[0] === now) {
      const [, task] = running.pop()
      idle++
      done++
      for (const next of dependents[task]) {
        if (--missing[next] === 0) ready.push(next)
      }
    }
  }
  return done === n ? now : -1
}
